package org.apache.commons.math.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.linear.Array2DRowRealMatrix;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CholeskyDecompositionImpl.getDeterminant().
 */
public class CholeskyDecompositionImpl_getDeterminant_TriageGen0Test {

    @Test
    public void testGetDeterminant_IdentityMatrix() {
        // For an Identity matrix, L is Identity.
        // det(L) = 1. det(L^T * L) = 1 * 1 = 1.
        RealMatrix matrix = MatrixUtils.createRealIdentityMatrix(3);
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 1.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetDeterminant_DiagonalMatrix() {
        // Matrix: [[4, 0], [0, 9]]
        // L should be [[2, 0], [0, 3]]
        // det = (2*2) * (3*3) = 4 * 9 = 36
        RealMatrix matrix = new Array2DRowRealMatrix(new double[][] {
            {4.0, 0.0},
            {0.0, 9.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 36.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetDeterminant_PositiveDefiniteMatrix() {
        // Matrix: [[1, 0.5], [0.5, 1]]
        // L = [[1, 0], [0.5, sqrt(0.75)]]
        // lTii values: 1.0, sqrt(0.75)
        // determinant = (1.0 * 1.0) * (sqrt(0.75) * sqrt(0.75)) = 0.75
        RealMatrix matrix = new Array2DRowRealMatrix(new double[][] {
            {1.0, 0.5},
            {0.5, 1.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 0.75;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetDeterminant_SingleElement() {
        // Matrix: [[25.0]]
        // L = [[5.0]]
        // det = 5.0 * 5.0 = 25.0
        RealMatrix matrix = new Array2DRowRealMatrix(new double[][] {
            {25.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 25.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-12);
    }

    @Test
    public void testGetDeterminant_LargeValues() {
        // Testing precision/scale
        double val = 1e4;
        RealMatrix matrix = new Array2DRowRealMatrix(new double[][] {
            {val * val, 0.0},
            {0.0, val * val}
        });
        // L = [[1e4, 0], [0, 1e4]]
        // det = (1e4^2) * (1e4^2) = 1e16
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 1e16;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-2); // Higher epsilon for large scale
    }
}
